import * as React from 'react';
import { CardContent, Grid, IconButton, TextField, Tooltip, Fab, Typography, Box, Chip, Checkbox } from '@mui/material';
// project imports
import MainCard from 'ui-component/cards/MainCard';
import { useDispatch, useSelector } from 'store';
import SearchIcon from '@mui/icons-material/Search';
import { getPromptCategoiresList } from 'store/slices/aiContent';
import DefaultImg from '../../../assets/images/landing/empty.png';
import CategoiresTemplate from './CategoiresTemplate';

// assets
import EditIcon from '@mui/icons-material/Edit';
import AddIcon from '@mui/icons-material/AddTwoTone';
import DeleteIcon from '@mui/icons-material/Delete';
import DeleteAlert from 'views/commons/alerts/deleteAlarts';
import useSnackbar from 'hooks/useSnackbar';
import GenericModelForm from 'views/commons/modelform/GenericModleForm';
import ApiRequest from 'utils/apiService';
import { useTheme } from '@mui/material/styles';
import useAuth from 'hooks/useAuth';
import { getPromptCategoiresModelFields, getPromptCategoiresModelFields1 } from 'store/constant';

const AiPromptTemplate = () => {
    const { user } = useAuth();
    const theme = useTheme();
    const dispatch = useDispatch();
    const { entities } = useSelector((state) => state.aiprompts);
    const categoiresPrompts = entities.categoiresPrompt || [];
    const [currentCategoryPrompts, setCurrentCategoryPrompts] = React.useState([]);
    const [selectedCategory, setSelectedCategory] = React.useState(null);
    const [open, setOpen] = React.useState(false);
    const { showSnackbar } = useSnackbar();
    const [editData, setEditData] = React.useState(null);
    const [loading, setLoading] = React.useState(false);
    const [searchTerm, setSearchTerm] = React.useState('');
    const [deletePromptId, setDeletePromptId] = React.useState(null);
    const [deleteDialogOpen, setDeleteDialogOpen] = React.useState(false);
    const [selectedPrompts, setSelectedPrompts] = React.useState([]);
    const [selectAll, setSelectAll] = React.useState(false);
    const lastSavedCategory = React.useRef(null);
    const [editCategoryData, setEditCategoryData] = React.useState(null);
    const [deleteCategoryId, setDeleteCategoryId] = React.useState(null);
    const [deleteCategoryDialogOpen, setDeleteCategoryDialogOpen] = React.useState(false);
    const [openCategoryDialog, setOpenCategoryDialog] = React.useState(false);
    const [categorySearchTerm, setCategorySearchTerm] = React.useState('');

    React.useEffect(() => {
        dispatch(getPromptCategoiresList({ pagination: false }));
    }, [dispatch]);

    const handleCategoryClick = (categoryId) => {
        const category = categoiresPrompts.find((cat) => cat.id === categoryId);
        if (category) {
            setSelectedCategory(category);
            setCurrentCategoryPrompts(category.prompts || []);
        }
    };

    const handleClickOpenDialog = () => {
        setOpen(true);
    };

    const handleCloseDialog = () => {
        setOpen(false);
        setEditData(null);
    };

    const handleEditPrompt = (prompt) => {
        setEditData(prompt);
        setOpen(true);
    };

    const handleDeletePrompt = (promptId) => {
        if (!promptId) return;
        setDeletePromptId(promptId);
        setDeleteDialogOpen(true);
    };

    React.useEffect(() => {
        if (!lastSavedCategory.current) return;

        const updatedCategory = entities.categoiresPrompt?.find((cat) => cat.id === lastSavedCategory.current);

        if (updatedCategory) {
            setSelectedCategory(updatedCategory);
            setCurrentCategoryPrompts(updatedCategory.prompts || []);
            lastSavedCategory.current = null; // reset
        }
    }, [entities.categoiresPrompt]);

    const handlePermissionSubmit = async (data, resetForm) => {
        setLoading(true);
        const url = editData ? `content-generator/categories/update/${editData.id}` : 'content-generator/prompts/add';
        const method = editData ? 'PUT' : 'POST';
        const defaultMessage = editData ? 'Category Update successfully!' : 'Category Add successfully!';

        const payload = { ...data };

        if (data?.category.length > 0) {
            payload.categoryId = data.category[0].id;
        }

        try {
            const response = await ApiRequest(method, url, payload);
            showSnackbar(response.message || defaultMessage, 'success');

            if (editData) {
                setCurrentCategoryPrompts((prev) =>
                    prev.map((p) => (p.id === editData.id ? { ...p, ...payload, updatedAt: new Date().toISOString() } : p))
                );
                setSelectedCategory((prev) => ({
                    ...prev,
                    prompts: prev.prompts.map((p) => (p.id === editData.id ? { ...p, ...payload, updatedAt: new Date().toISOString() } : p))
                }));
            } else {
                lastSavedCategory.current = payload.categoryId;
                await dispatch(getPromptCategoiresList({ pagination: false }));
            }

            resetForm();
        } catch (error) {
            showSnackbar(error.message, 'error');
        } finally {
            setLoading(false);
            setOpen(false);
            setEditData(null);
        }
    };

    // Handle successful deletion from DeleteAlert
    const handleDeleteSuccess = () => {
        if (!deletePromptId) return;

        // Update UI state
        setCurrentCategoryPrompts((prev) => prev.filter((prompt) => prompt.id !== deletePromptId));

        // Update selected category
        setSelectedCategory((prev) => ({
            ...prev,
            prompts: prev.prompts.filter((p) => p.id !== deletePromptId)
        }));

        showSnackbar('Prompt deleted successfully!', 'success');
        setDeleteDialogOpen(false);
        setDeletePromptId(null);
    };

    const filteredPrompts = currentCategoryPrompts.filter((prompt) => prompt.title.toLowerCase().includes(searchTerm.toLowerCase()));

    const handleSelectAll = (event) => {
        const isChecked = event.target.checked;
        setSelectAll(isChecked);
        if (isChecked) {
            setSelectedPrompts(filteredPrompts.map((prompt) => prompt.id));
        } else {
            setSelectedPrompts([]);
        }
    };

    const handleSelectPrompt = (event, promptId) => {
        if (event.target.checked) {
            setSelectedPrompts([...selectedPrompts, promptId]);
        } else {
            setSelectedPrompts(selectedPrompts.filter((id) => id !== promptId));
            setSelectAll(false);
        }
    };

    const handleBulkDelete = () => {
        if (selectedPrompts.length === 0) return;
        setDeletePromptId(selectedPrompts);
        setDeleteDialogOpen(true);
    };
    // Render content based on conditions
    const renderContent = () => {
        if (!selectedCategory) {
            return (
                <Box
                    sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        p: 8,
                        minHeight: '100%'
                    }}
                >
                    <Box
                        component="img"
                        src={DefaultImg}
                        alt="Select a category"
                        sx={{
                            width: 200,
                            height: 200,
                            mb: 2,
                            opacity: 0.7
                        }}
                    />
                    <Typography variant="h5" color="textSecondary">
                        Select a category
                    </Typography>
                    <Typography variant="body1" color="textSecondary" sx={{ mt: 1 }}>
                        Choose a category from the left panel to view its prompts
                    </Typography>
                </Box>
            );
        }

        if (filteredPrompts.length === 0) {
            return (
                <Box
                    sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        p: 8,
                        minHeight: '100%'
                    }}
                >
                    <Box
                        component="img"
                        src={DefaultImg}
                        alt="No prompts"
                        sx={{
                            width: 200,
                            height: 200,
                            mb: 2,
                            opacity: 0.7
                        }}
                    />
                    <Typography variant="h5" color="textSecondary">
                        No prompts found
                    </Typography>
                    <Typography variant="body1" color="textSecondary" sx={{ mt: 1 }}>
                        {searchTerm ? 'No prompts match your search' : 'This category has no prompts yet'}
                    </Typography>
                </Box>
            );
        }

        return (
            <Box sx={{ width: '100%', bgcolor: 'white', boxShadow: 2 }}>
                {/* Table Header */}
                <Box
                    sx={{
                        display: 'flex',
                        alignItems: 'center',
                        p: 2,
                        borderBottom: '1px solid',
                        borderColor: 'divider',
                        bgcolor: 'background.paper',
                        fontWeight: 'bold'
                    }}
                >
                    <Box sx={{ width: '5%' }}>
                        <Checkbox
                            checked={selectAll}
                            onChange={handleSelectAll}
                            indeterminate={selectedPrompts.length > 0 && selectedPrompts.length < filteredPrompts.length}
                        />
                    </Box>
                    <Box sx={{ width: '25%' }}>
                        <Typography variant="subtitle1" color="textPrimary" fontWeight={600}>
                            Title
                        </Typography>
                    </Box>
                    <Box sx={{ width: '50%' }}>
                        <Typography variant="subtitle1" color="textPrimary" fontWeight={600}>
                            Prompt
                        </Typography>
                    </Box>
                    <Box sx={{ width: '10%', textAlign: 'center' }}>
                        <Typography variant="subtitle1" color="textPrimary" fontWeight={600}>
                            Status
                        </Typography>
                    </Box>
                    <Box sx={{ width: '10%', textAlign: 'center' }}>
                        <Typography variant="subtitle1" color="textPrimary" fontWeight={600}>
                            Actions
                        </Typography>
                    </Box>
                </Box>

                {/* Table Rows */}
                {filteredPrompts.map((prompt) => (
                    <Box
                        key={prompt.id}
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            p: 2,
                            borderBottom: '1px solid',
                            borderColor: 'divider',
                            '&:hover': {
                                backgroundColor: theme.palette.action.hover
                            }
                        }}
                    >
                        <Box sx={{ width: '5%' }}>
                            <Checkbox checked={selectedPrompts.includes(prompt.id)} onChange={(e) => handleSelectPrompt(e, prompt.id)} />
                        </Box>
                        <Box sx={{ width: '25%' }}>
                            <Typography variant="body1" color="text.dark" noWrap>
                                {prompt.title}
                            </Typography>
                        </Box>
                        <Box sx={{ width: '50%' }}>
                            <Typography
                                variant="body2"
                                color="text.dark"
                                sx={{
                                    display: '-webkit-box',
                                    WebkitLineClamp: 2,
                                    WebkitBoxOrient: 'vertical',
                                    overflow: 'hidden'
                                }}
                            >
                                {prompt.prompt || 'No prompt available'}
                            </Typography>
                        </Box>
                        <Box sx={{ width: '10%', textAlign: 'center' }}>
                            <Chip
                                label={prompt.status ? 'Active' : 'Inactive'}
                                color={prompt.status ? 'success' : 'default'}
                                size="small"
                            />
                        </Box>
                        <Box sx={{ width: '10%', display: 'flex', justifyContent: 'center' }}>
                            <Tooltip title="Edit Prompt">
                                <IconButton edge="end" aria-label="edit" onClick={() => handleEditPrompt(prompt)} sx={{ mr: 1 }}>
                                    <EditIcon color="primary" />
                                </IconButton>
                            </Tooltip>
                            <Tooltip title="Delete Prompt">
                                <IconButton
                                    disabled={!!selectAll}
                                    edge="end"
                                    aria-label="delete"
                                    onClick={() => handleDeletePrompt(prompt.id)}
                                >
                                    <DeleteIcon color={selectAll ? 'disabled' : 'error'} />
                                </IconButton>
                            </Tooltip>
                        </Box>
                    </Box>
                ))}
            </Box>
        );
    };

    const handleEditCategory = (category) => {
        setEditCategoryData(category);
        setOpenCategoryDialog(true);
    };

    const handleDeleteCategory = (category) => {
        setDeleteCategoryId(category.id);
        setDeleteCategoryDialogOpen(true);
    };

    const handleAddCategory = () => {
        setEditCategoryData(null);
        setOpenCategoryDialog(true);
    };

    const handleCategoryDeleteSuccess = () => {
        if (!deleteCategoryId) return;

        // Refresh categories list
        dispatch(getPromptCategoiresList({ pagination: false }));

        // Reset selected category if it was deleted
        if (selectedCategory && selectedCategory.id === deleteCategoryId) {
            setSelectedCategory(null);
            setCurrentCategoryPrompts([]);
        }

        showSnackbar('Category deleted successfully!', 'success');
        setDeleteCategoryDialogOpen(false);
        setDeleteCategoryId(null);
    };

    const handleCategorySubmit = async (data, resetForm) => {
        setLoading(true);
        const url = editCategoryData ? `content-generator/categories/update/${editCategoryData.id}` : 'content-generator/categories/add';
        const method = editCategoryData ? 'PUT' : 'POST';
        const defaultMessage = editCategoryData ? 'Category updated successfully!' : 'Category added successfully!';

        try {
            const response = await ApiRequest(method, url, data);
            showSnackbar(response.message || defaultMessage, 'success');

            // Refresh categories list
            await dispatch(getPromptCategoiresList({ pagination: false }));

            resetForm();
            setOpenCategoryDialog(false);
        } catch (error) {
            showSnackbar(error.message, 'error');
        } finally {
            setLoading(false);
            setEditCategoryData(null);
        }
    };

    return (
        <Grid container spacing={1} sx={{ p: 3 }}>
            <Grid item xs={12} md={3}>
                <CategoiresTemplate
                    categories={categoiresPrompts}
                    handleCategoryClick={handleCategoryClick}
                    categorySearchTerm={categorySearchTerm} // New prop
                    setCategorySearchTerm={setCategorySearchTerm} // New prop
                    setSearchTerm={setSearchTerm}
                    searchTerm={searchTerm}
                    selectedCategory={selectedCategory}
                    onEditCategory={handleEditCategory} // Pass edit handler
                    onDeleteCategory={handleDeleteCategory} // Pass delete handler
                    onAddCategory={handleAddCategory} // Pass add handler
                />
            </Grid>
            <Grid item xs={12} md={9}>
                <MainCard content={false} sx={{ background: 'white', border: `1px solid ${theme.palette.divider}` }}>
                    <CardContent>
                        <Grid container justifyContent="space-between" alignItems="center" spacing={0} sx={{ mb: 2 }}>
                            <Grid item>
                                {selectedCategory && (
                                    <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center' }}>
                                        {selectedCategory.name} Prompts
                                        <Chip
                                            label={`${currentCategoryPrompts.length} prompts`}
                                            size="small"
                                            sx={{ ml: 1, background: '#01586A', color: 'white' }}
                                        />
                                    </Typography>
                                )}
                            </Grid>
                            <Grid item>
                                <TextField
                                    size="small"
                                    placeholder="Search prompts..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    InputProps={{
                                        startAdornment: <SearchIcon fontSize="medium" sx={{ mr: 1, color: theme.palette.primary.dark }} />
                                    }}
                                    sx={{ width: 250, mr: 1 }}
                                />
                                {selectedPrompts.length > 0 && (
                                    <Tooltip title="Delete Selected">
                                        <IconButton
                                            onClick={handleBulkDelete}
                                            sx={{
                                                mr: 1,
                                                color: 'error.main',
                                                '&:hover': {
                                                    backgroundColor: 'error.light',
                                                    color: 'error.dark'
                                                }
                                            }}
                                        >
                                            <DeleteIcon />
                                        </IconButton>
                                    </Tooltip>
                                )}
                                <Tooltip title="Add New Prompt">
                                    <Fab color="primary" size="small" onClick={handleClickOpenDialog} sx={{ boxShadow: 'none' }}>
                                        <AddIcon />
                                    </Fab>
                                </Tooltip>
                            </Grid>
                        </Grid>

                        {renderContent()}
                    </CardContent>
                </MainCard>

                {/* Delete Confirmation Dialog */}
                <DeleteAlert
                    open={deleteDialogOpen}
                    onClose={() => {
                        setDeleteDialogOpen(false);
                        setDeletePromptId(null);
                    }}
                    selectedIds={deletePromptId ? [deletePromptId] : []}
                    endpoint="content-generator/prompts/delete" // Corrected endpoint
                    onDeleteSuccess={handleDeleteSuccess}
                    message="Are you sure you want to delete this prompt?"
                />

                {/* Prompt Form Dialog */}
                <GenericModelForm
                    open={open}
                    handleCloseDialog={handleCloseDialog}
                    position="center"
                    fields={getPromptCategoiresModelFields(categoiresPrompts)}
                    onSubmit={handlePermissionSubmit}
                    formLabel={editData ? 'Edit Prompt' : 'Add New Prompt'}
                    editData={editData}
                />

                <DeleteAlert
                    open={deleteCategoryDialogOpen}
                    onClose={() => {
                        setDeleteCategoryDialogOpen(false);
                        setDeleteCategoryId(null);
                    }}
                    selectedIds={deleteCategoryId ? [deleteCategoryId] : []}
                    endpoint="content-generator/categories/delete"
                    onDeleteSuccess={handleCategoryDeleteSuccess}
                    message="Are you sure you want to delete this category?"
                />

                <GenericModelForm
                    open={openCategoryDialog}
                    handleCloseDialog={() => setOpenCategoryDialog(false)}
                    position="center"
                    fields={getPromptCategoiresModelFields1()} // Make sure this function exists
                    onSubmit={handleCategorySubmit}
                    formLabel={editCategoryData ? 'Edit Category' : 'Add New Category'}
                    editData={editCategoryData}
                />
            </Grid>
        </Grid>
    );
};

export default AiPromptTemplate;
