import { Grid, TextField, Box, Typography, IconButton, Card, CardContent, Divider, Fab, Tooltip, Menu, MenuItem } from '@mui/material';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import useAuth from 'hooks/useAuth';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/AddTwoTone';
import { useState } from 'react';
import { useTheme } from '@mui/system';

const CategoriesTemplate = ({
    categories,
    handleCategoryClick,
    categorySearchTerm, // Receive new prop
    setCategorySearchTerm, // Receive new prop
    setSearchTerm,
    searchTerm,
    onEditCategory, // New prop for edit handling
    onDeleteCategory, // New prop for delete handling
    onAddCategory // New prop for add handling
}) => {
    const { user } = useAuth();
    const [anchorEl, setAnchorEl] = useState(null);
    const [currentCategory, setCurrentCategory] = useState(null);
    const theme = useTheme();
    const filteredCategories = categories.filter((category) => category.name.toLowerCase().includes(categorySearchTerm.toLowerCase()));

    const handleMenuClick = (event, category) => {
        setAnchorEl(event.currentTarget);
        setCurrentCategory(category);
    };

    const handleMenuClose = () => {
        setAnchorEl(null);
        setCurrentCategory(null);
    };

    const handleEdit = () => {
        if (currentCategory) {
            onEditCategory(currentCategory);
            handleMenuClose();
        }
    };

    const handleDelete = () => {
        if (currentCategory) {
            onDeleteCategory(currentCategory);
            handleMenuClose();
        }
    };

    return (
        <Card
            sx={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                background: 'white',
                border: '2px solid gray',
                boxShadow: '3'
            }}
        >
            <CardContent>
                {/* Header with title and back button */}
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                    <TextField
                        size="small"
                        placeholder="Search prompts..."
                        value={categorySearchTerm}
                        onChange={(e) => setCategorySearchTerm(e.target.value)}
                        InputProps={{
                            startAdornment: <SearchIcon fontSize="medium" sx={{ mr: 1, color: theme.palette.primary.dark }} />
                        }}
                        sx={{ width: '80%', border: '0.5px solid gray', borderRadius: '10px' }}
                    />
                    <Tooltip title="Add Client">
                        <Fab
                            color="primary"
                            size="small"
                            onClick={onAddCategory} // Fixed: added onClick handler
                            sx={{ boxShadow: 'none', ml: 1, width: 30, height: 30, minHeight: 30 }}
                        >
                            <AddIcon fontSize="small" />
                        </Fab>
                    </Tooltip>
                </Box>

                <Divider sx={{ my: 2 }} />

                {/* Content Area */}
                <Box
                    sx={{
                        overflowY: 'auto',
                        height: '100vh',
                        pr: 1,
                        '&::-webkit-scrollbar': { width: '6px' },
                        '&::-webkit-scrollbar-thumb': { bgcolor: 'divider' }
                    }}
                >
                    <Typography variant="subtitle1" sx={{ mb: 1, mt: 3 }}>
                        Categories
                    </Typography>
                    <Grid container spacing={1} sx={{ mb: 2 }}>
                        {filteredCategories?.map((category) => (
                            <Grid item xs={6} key={category.id}>
                                <Box
                                    sx={{
                                        p: 1.5,
                                        border: '2px solid gray',
                                        borderRadius: 1,
                                        borderColor: 'divider',
                                        textAlign: 'center',
                                        cursor: 'pointer',
                                        bgcolor: 'white',
                                        position: 'relative', // Added for positioning menu
                                        '&:hover': {
                                            bgcolor: 'action.hover'
                                        }
                                    }}
                                >
                                    {/* Three-dot menu button */}
                                    <IconButton
                                        size="small"
                                        sx={{
                                            position: 'absolute',
                                            top: 4,
                                            right: 4,
                                            '&:hover': { backgroundColor: 'rgba(0,0,0,0.05)' }
                                        }}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleMenuClick(e, category);
                                        }}
                                    >
                                        <MoreVertIcon fontSize="small" />
                                    </IconButton>

                                    {/* Category content */}
                                    <Box onClick={() => handleCategoryClick(category.id)}>
                                        <Typography variant="h1" sx={{ mb: 0.5 }}>
                                            <i className="fas fa-box" />
                                        </Typography>

                                        <Typography variant="body3" color="text.dark">
                                            {category.name}
                                        </Typography>
                                    </Box>
                                </Box>
                            </Grid>
                        ))}
                    </Grid>
                </Box>
            </CardContent>

            {/* Context Menu */}
            <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={handleMenuClose}
                anchorOrigin={{
                    vertical: 'top',
                    horizontal: 'right'
                }}
                transformOrigin={{
                    vertical: 'top',
                    horizontal: 'right'
                }}
                PaperProps={{
                    sx: {
                        backgroundColor: 'white', // background of the menu
                        color: theme.palette.primary.dark // default text color
                    }
                }}
            >
                <MenuItem onClick={handleEdit}>Edit</MenuItem>
                <MenuItem onClick={handleDelete}>Delete</MenuItem>
            </Menu>
        </Card>
    );
};

export default CategoriesTemplate;
